 private static final class CalProjection{long qualified,fitted;}
 /** READY labels input availability. Quality counts execute the same policy/hash evaluator as the inference consumer. */
 private static CalProjection calibrationProjectionCP12(ReportReadContextCP4 ctx,ReportTextCP12 out){CalProjection result=new CalProjection();out.append("\nCP12_CALIBRATION_INPUT_STATES\n");try(android.database.Cursor rows=ctx.select("SELECT state,COUNT(*) FROM "+CandidateCalibrationR932.STUDY+" GROUP BY state ORDER BY state",null)){while(rows.moveToNext()){ctx.checkpoint();String raw=rows.getString(0);CandidateCalibrationR932.CalibrationInputState mapped=CandidateCalibrationR932.inputStateCP12(raw);out.append("stored=").append(raw).append("|inputState=").append(mapped.name()).append("|n=").append(rows.getLong(1)).append("\n");}}
  String cursor="";for(;;){java.util.ArrayList<String> studies=new java.util.ArrayList<>(32);try(android.database.Cursor rows=ctx.select("SELECT study_hash FROM "+CandidateCalibrationR932.MODEL+" WHERE study_hash>? ORDER BY study_hash LIMIT 32",new String[]{cursor})){while(rows.moveToNext()){String study=rows.getString(0);if(study==null||!study.matches("[0-9a-f]{64}"))throw new ReportReadContextCP4.ReportReadFailureCP4("REPORT_CAL_STUDY_HASH");studies.add(study);}}
   if(studies.isEmpty())break;for(String study:studies){ctx.checkpoint();CandidateCalibrationR932.Qualification q=CandidateCalibrationR932.qualificationForStudySnapshotCP12(ctx,study);result.fitted++;if(q.qualified())result.qualified++;out.append("study=").append(study).append("|qualification=").append(q.state.name()).append("|reason=").append(q.reason).append("|ece=").append(q.ece).append("|brier=").append(q.brier).append("|baselineBrier=").append(q.baselineBrier).append("|validationUntil=").append(q.validationUntil).append("\n");}cursor=studies.get(studies.size()-1);}
  out.append("fittedAssets=").append(result.fitted).append("|qualifiedAssets=").append(result.qualified).append("|scope=SNAPSHOT_MODEL_ASSETS_NOT_MAINLINE_AUTHORIZATION\n");return result;
 } private static void appendMoleculeCheckpointCP12(ReportReadContextCP4 ctx,ReportTextCP12 out){
  final String table=com.ethk3.novaonepro.r952.ModernSeedFactoryCP12.CHECKPOINT;
  try(android.database.Cursor exists=ctx.select("SELECT 1 FROM sqlite_master WHERE type='table' AND name=?",new String[]{table})){
   if(!exists.moveToFirst()){out.append("\nMOLECULE_CHECKPOINT_NOT_INSTALLED|usableCatalog=false|trainingProof=NOT_GRANTED|realAuthority=NOT_GRANTED\n");return;}
  }
  try(android.database.Cursor c=ctx.select("SELECT state,legacy_target_row,scan_row,scan_offset,scan_prefix,material_row,material_offset,material_prefix,generation,expected_rows,expected_bytes FROM "+table+" WHERE source_hash=? AND asset_name=?",new String[]{com.ethk3.novaonepro.r952.ModernSeedFactoryCP12.ASSET_SHA,com.ethk3.novaonepro.r952.ModernSeedFactoryCP12.ASSET})){
   if(!c.moveToFirst()){out.append("\nMOLECULE_NOT_STARTED|usableCatalog=false|trainingProof=NOT_GRANTED|realAuthority=NOT_GRANTED\n");return;}
   final String sha=com.ethk3.novaonepro.r952.ModernSeedFactoryCP12.ASSET_SHA;
   boolean expected=c.getInt(9)==4200&&c.getLong(10)==3265020;
   boolean rawVerified=expected&&c.getInt(2)==4200&&c.getLong(3)==3265020&&sha.equals(c.getString(4));
   boolean usable=rawVerified&&"COMPLETE".equals(c.getString(0))&&c.getInt(5)==4200&&c.getLong(6)==3265020&&sha.equals(c.getString(7));
   out.append("\nMOLECULE_CATALOG_CHECKPOINT|phase=").append(c.getString(0)).append("|legacyRows=").append(c.getLong(1))
    .append("|rawScanRow=").append(c.getLong(2)).append("|rawScanOffset=").append(c.getLong(3)).append("|rawScanPrefix=").append(c.getString(4))
    .append("|rawVerifiedRows=").append(rawVerified?4200:0).append("|typedMaterializedRows=").append(c.getLong(5))
    .append("|typedOffset=").append(c.getLong(6)).append("|typedPrefix=").append(c.getString(7)).append("|generation=").append(c.getLong(8))
    .append("|usableCatalog=").append(Boolean.toString(usable)).append("|evidence=").append(usable?"ASSET_VERIFIED":"CATALOG_NOT_READY")
    .append("|trainingProof=NOT_GRANTED_BY_ASSET_IMPORT|realAuthority=NOT_GRANTED_BY_ASSET_IMPORT\n");
  }
 }

